50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    private final OwnerRequestValidator ownerRequestValidator;
71	
72	    private final HouseholdDuplicateValidator householdDuplicateValidator;
73	
74	    private final TelephoneNormalizer telephoneNormalizer;
75	
76	    private final EmailNormalizer emailNormalizer;
77	
78	    private final CustomerCodeGenerator customerCodeGenerator;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper,
84	                                 OwnerRequestValidator ownerRequestValidator,
85	                                 HouseholdDuplicateValidator householdDuplicateValidator,
86	                                 TelephoneNormalizer telephoneNormalizer,
87	                                 EmailNormalizer emailNormalizer,
88	                                 CustomerCodeGenerator customerCodeGenerator) {
89	        this.clinicService = clinicService;
90	        this.ownerMapper = ownerMapper;
91	        this.petMapper = petMapper;
92	        this.visitMapper = visitMapper;
93	        this.ownerRequestValidator = ownerRequestValidator;
94	        this.householdDuplicateValidator = householdDuplicateValidator;
95	        this.telephoneNormalizer = telephoneNormalizer;
96	        this.emailNormalizer = emailNormalizer;
97	        this.customerCodeGenerator = customerCodeGenerator;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        this.ownerRequestValidator.validate(ownerFieldsDto);
129	        this.householdDuplicateValidator.validate(ownerFieldsDto);
130	        String telephone = this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
131	        ownerFieldsDto.setTelephone(telephone);
132	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
133	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
134	            throw new DuplicateTelephoneException(telephone);
135	        }
136	        HttpHeaders headers = new HttpHeaders();
137	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
138	        owner.setCustomerCode(
139	            this.customerCodeGenerator.generate(owner.getLastName(), this.clinicService.countOwners()));
140	        this.clinicService.saveOwner(owner);
141	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
142	        headers.setLocation(UriComponentsBuilder.newInstance()
143	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
144	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
150	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
151	        if (currentOwner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        currentOwner.setAddress(ownerFieldsDto.getAddress());
155	        currentOwner.setCity(ownerFieldsDto.getCity());
156	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
157	        currentOwner.setLastName(ownerFieldsDto.getLastName());
158	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
159	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
160	        this.clinicService.saveOwner(currentOwner);
161	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Transactional
166	    @Override
167	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        this.clinicService.deleteOwner(owner);
173	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        HttpHeaders headers = new HttpHeaders();
184	        Pet pet = petMapper.toPet(petFieldsDto);
185	        owner.setId(ownerId);
186	        pet.setOwner(owner);
187	        pet.getType().setName(null);
188	        this.clinicService.savePet(pet);
189	        PetDto petDto = petMapper.toPetDto(pet);
190	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
191	            .buildAndExpand(pet.getId()).toUri());
192	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
198	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
199	        if (currentOwner != null) {
200	            Pet currentPet = this.clinicService.findPetById(petId);
201	            if (currentPet != null) {
202	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
203	                currentPet.setName(petFieldsDto.getName());
204	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
205	                this.clinicService.savePet(currentPet);
206	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
207	            }
208	        }
209	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
215	        HttpHeaders headers = new HttpHeaders();
216	        Visit visit = visitMapper.toVisit(visitFieldsDto);
217	        Pet pet = new Pet();
218	        pet.setId(petId);
219	        visit.setPet(pet);
220	        this.clinicService.saveVisit(visit);
221	        VisitDto visitDto = visitMapper.toVisitDto(visit);
222	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
223	            .buildAndExpand(visit.getId()).toUri());
224	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
225	    }
226	
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
231	        Owner owner = this.clinicService.findOwnerById(ownerId);
232	        if (owner != null) {
233	            Pet pet = owner.getPet(petId);
234	            if (pet != null) {
235	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
236	            }
237	        }
238	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
239	    }
240	}
