17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.ArrayList;
20	import java.util.LinkedHashMap;
21	import java.util.List;
22	import java.util.Map;
23	
24	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
25	import org.springframework.samples.petclinic.rest.error.RequiredFieldsMissingException;
26	import org.springframework.stereotype.Component;
27	import org.springframework.util.StringUtils;
28	
29	/**
30	 * Validates that an owner submitted to the REST API carries all of its mandatory fields.
31	 * A field is considered missing when it is {@code null}, empty or blank (whitespace only).
32	 */
33	@Component
34	public class OwnerRequestValidator {
35	
36	    /**
37	     * @param owner the submitted owner fields
38	     * @throws RequiredFieldsMissingException if any required field is missing or blank, naming
39	     * every offending field
40	     */
41	    public void validate(OwnerFieldsDto owner) {
42	        Map<String, String> requiredFields = new LinkedHashMap<>();
43	        requiredFields.put("firstName", owner.getFirstName());
44	        requiredFields.put("lastName", owner.getLastName());
45	        requiredFields.put("address", owner.getAddress());
46	        requiredFields.put("city", owner.getCity());
47	        requiredFields.put("telephone", owner.getTelephone());
48	
49	        List<String> missingFields = new ArrayList<>();
50	        requiredFields.forEach((name, value) -> {
51	            if (!StringUtils.hasText(value)) {
52	                missingFields.add(name);
53	            }
54	        });
55	
56	        if (!missingFields.isEmpty()) {
57	            throw new RequiredFieldsMissingException(missingFields);
58	        }
59	    }
60	}
