17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Locale;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
23	import org.springframework.samples.petclinic.rest.error.DuplicateHouseholdException;
24	import org.springframework.samples.petclinic.service.ClinicService;
25	import org.springframework.stereotype.Component;
26	
27	/**
28	 * Rejects creating an owner that would share a household with an existing one - that is, another
29	 * owner with the same last name and the same address, compared case-insensitively and with
30	 * collapsed whitespace. The request may opt in to the shared household via
31	 * {@link OwnerFieldsDto#getSharesHousehold()}, in which case the duplicate is allowed.
32	 */
33	@Component
34	public class HouseholdDuplicateValidator {
35	
36	    private final ClinicService clinicService;
37	
38	    public HouseholdDuplicateValidator(ClinicService clinicService) {
39	        this.clinicService = clinicService;
40	    }
41	
42	    /**
43	     * @param owner the submitted owner fields
44	     * @throws DuplicateHouseholdException if another owner already shares the same last name and
45	     * address and the request did not set {@code sharesHousehold} to {@code true}
46	     */
47	    public void validate(OwnerFieldsDto owner) {
48	        if (Boolean.TRUE.equals(owner.getSharesHousehold())) {
49	            return;
50	        }
51	        String lastName = normalize(owner.getLastName());
52	        String address = normalize(owner.getAddress());
53	        boolean duplicate = this.clinicService.findAllOwners().stream()
54	            .anyMatch(existing -> normalize(existing.getLastName()).equals(lastName)
55	                && normalize(existing.getAddress()).equals(address));
56	        if (duplicate) {
57	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
58	        }
59	    }
60	
61	    /** Lower-case and collapse runs of whitespace to a single space so trivial formatting
62	     *  differences do not defeat the household comparison. */
63	    private static String normalize(String value) {
64	        if (value == null) {
65	            return "";
66	        }
67	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
68	    }
69	}
