17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import org.springframework.samples.petclinic.rest.error.InvalidTelephoneException;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Normalizes a submitted telephone number into E.164 form. A leading '+' and country code are kept
24	 * when present; otherwise the default country code '+61' is assumed and a single leading '0' is
25	 * dropped from the national digits. Spaces, dashes and brackets are stripped, and the result must
26	 * hold between 8 and 15 digits after the '+'.
27	 */
28	@Component
29	public class TelephoneNormalizer {
30	
31	    private static final String DEFAULT_COUNTRY_CODE = "61";
32	
33	    /** Characters used only for human-readable grouping and removed before parsing. */
34	    private static final String FORMATTING_CHARS = "[\\s\\-()\\[\\]]";
35	
36	    private static final int MIN_DIGITS = 8;
37	    private static final int MAX_DIGITS = 15;
38	
39	    /**
40	     * @param telephone the raw, possibly formatted telephone number
41	     * @return the telephone in E.164 form (a '+' followed by 8 to 15 digits)
42	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
43	     */
44	    public String normalize(String telephone) {
45	        if (telephone == null) {
46	            throw new InvalidTelephoneException(null);
47	        }
48	        String cleaned = telephone.trim().replaceAll(FORMATTING_CHARS, "");
49	        String digits;
50	        if (cleaned.startsWith("+")) {
51	            digits = cleaned.substring(1);
52	        } else {
53	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
54	            digits = DEFAULT_COUNTRY_CODE + national;
55	        }
56	        if (!digits.matches("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}")) {
57	            throw new InvalidTelephoneException(telephone);
58	        }
59	        return "+" + digits;
60	    }
61	}
