130	    /**
131	     * Handles exception thrown by Bean Validation on controller methods parameters
132	     *
133	     * @param e The {@link MethodArgumentNotValidException} to be handled
134	     * @param request {@link HttpServletRequest} object referring to the current request.
135	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
136	     */
137	    @ExceptionHandler(MethodArgumentNotValidException.class)
138	    @ResponseBody
139	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
140	        HttpStatus status = HttpStatus.BAD_REQUEST;
141	        BindingErrorsResponse errors = new BindingErrorsResponse();
142	        BindingResult bindingResult = e.getBindingResult();
143	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
144	        if (bindingResult.hasErrors()) {
145	            errors.addAllErrors(bindingResult);
146	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
147	                .map(fieldError -> fieldError.getField())
148	                .distinct()
149	                .toList();
150	            detail.setProperty("errors", invalidFields);
151	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
152	                .map(fieldError -> {
153	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
154	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
155	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
156	                        fieldError.getField(),
157	                        defaultMessage,
158	                        rejectedValue);
159	                    return new ValidationMessageDto(message)
160	                        .putAdditionalProperty("field", fieldError.getField())
161	                        .putAdditionalProperty("rejectedValue", rejectedValue)
162	                        .putAdditionalProperty("defaultMessage", defaultMessage);
163	                })
164	                .toList();
165	            logger.debug("Validation error at {} {}: {}",
166	                request.getMethod(),
167	                request.getRequestURI(),
168	                bindingResult.getFieldErrors());
169	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
170	            return ResponseEntity.status(status).body(detail);
171	        }
172	        return ResponseEntity.status(status).body(detail);
173	    }
